diff --git a/src/pages/content/folder/__tests__/conversationDragToFolder.test.ts b/src/pages/content/folder/__tests__/conversationDragToFolder.test.ts
new file mode 100644
index 0000000..4a23843
--- /dev/null
+++ b/src/pages/content/folder/__tests__/conversationDragToFolder.test.ts
@@ -0,0 +1,260 @@
+import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
+
+import { FolderManager } from '../manager';
+import type { Folder, FolderData } from '../types';
+
+vi.mock('@/utils/i18n', () => ({
+  getTranslationSync: (key: string) => key,
+  getTranslationSyncUnsafe: (key: string) => key,
+  initI18n: () => Promise.resolve(),
+}));
+
+type TestableFolderManager = {
+  data: FolderData;
+  createFolderElement: (folder: Folder, level?: number) => HTMLElement;
+  saveData: () => void;
+  refresh: () => void;
+};
+
+describe('conversation drag and drop into folder conversations', () => {
+  let manager: FolderManager | null = null;
+
+  beforeEach(() => {
+    vi.useFakeTimers();
+  });
+
+  afterEach(() => {
+    manager?.destroy();
+    manager = null;
+    document.body.innerHTML = '';
+    vi.runOnlyPendingTimers();
+    vi.useRealTimers();
+  });
+
+  function setupManagerWithFolder(): {
+    typedManager: TestableFolderManager;
+    folder: Folder;
+    folderEl: HTMLElement;
+  } {
+    manager = new FolderManager();
+    const typedManager = manager as unknown as TestableFolderManager;
+
+    // Mock saveData and refresh to avoid DOM pollution and side effects
+    vi.spyOn(typedManager, 'saveData').mockImplementation(() => {});
+    vi.spyOn(typedManager, 'refresh').mockImplementation(() => {});
+
+    const now = Date.now();
+    const folder: Folder = {
+      id: 'folder-target',
+      name: 'Target Folder',
+      parentId: null,
+      isExpanded: true,
+      createdAt: now,
+      updatedAt: now,
+    };
+
+    typedManager.data.folders = [folder];
+    typedManager.data.folderContents['folder-target'] = [
+      {
+        conversationId: 'c_existing_1',
+        title: 'Existing Conversation 1',
+        url: 'https://gemini.google.com/app/1',
+        addedAt: now - 2000,
+        sortIndex: 0,
+      },
+      {
+        conversationId: 'c_existing_2',
+        title: 'Existing Conversation 2',
+        url: 'https://gemini.google.com/app/2',
+        addedAt: now - 1000,
+        sortIndex: 1,
+      },
+    ];
+
+    const folderEl = typedManager.createFolderElement(folder);
+    document.body.appendChild(folderEl);
+
+    return { typedManager, folder, folderEl };
+  }
+
+  function simulateDropOnConversation(
+    convEl: HTMLElement,
+    dragData: Record<string, unknown>,
+    isAbove = true,
+  ): void {
+    if (isAbove) {
+      convEl.classList.add('gv-reorder-above');
+    } else {
+      convEl.classList.add('gv-reorder-below');
+    }
+
+    const dropEvent = new Event('drop', { bubbles: true, cancelable: true }) as Event & {
+      dataTransfer: { getData: (type: string) => string };
+    };
+
+    dropEvent.dataTransfer = {
+      getData: (type: string) => {
+        if (type === 'application/json') {
+          return JSON.stringify(dragData);
+        }
+        return '';
+      },
+    };
+
+    convEl.dispatchEvent(dropEvent);
+  }
+
+  it('successfully drops a single native sidebar conversation into an existing conversation in a folder', () => {
+    const { typedManager, folderEl } = setupManagerWithFolder();
+
+    const convEls = folderEl.querySelectorAll('.gv-folder-conversation');
+    expect(convEls.length).toBe(2);
+
+    // Drop native conversation above c_existing_1
+    simulateDropOnConversation(
+      convEls[0] as HTMLElement,
+      {
+        type: 'conversation',
+        conversationId: 'c_native_new',
+        title: 'New Native Conversation',
+        url: 'https://gemini.google.com/app/new',
+        isGem: false,
+      },
+      true, // isAbove
+    );
+
+    const targetContents = typedManager.data.folderContents['folder-target'];
+    expect(targetContents.length).toBe(3);
+    expect(targetContents[0].conversationId).toBe('c_native_new');
+    expect(targetContents[0].title).toBe('New Native Conversation');
+    expect(targetContents[0].sortIndex).toBe(0);
+    expect(targetContents[1].conversationId).toBe('c_existing_1');
+    expect(targetContents[1].sortIndex).toBe(1);
+    expect(targetContents[2].conversationId).toBe('c_existing_2');
+    expect(targetContents[2].sortIndex).toBe(2);
+  });
+
+  it('successfully drops a native conversation below an existing conversation in a folder', () => {
+    const { typedManager, folderEl } = setupManagerWithFolder();
+
+    const convEls = folderEl.querySelectorAll('.gv-folder-conversation');
+    expect(convEls.length).toBe(2);
+
+    // Drop native conversation below c_existing_1 (insertIndex = 1)
+    simulateDropOnConversation(
+      convEls[0] as HTMLElement,
+      {
+        type: 'conversation',
+        conversationId: 'c_native_middle',
+        title: 'Middle Native Conversation',
+        url: 'https://gemini.google.com/app/middle',
+        isGem: false,
+      },
+      false, // isBelow
+    );
+
+    const targetContents = typedManager.data.folderContents['folder-target'];
+    expect(targetContents.length).toBe(3);
+    expect(targetContents[0].conversationId).toBe('c_existing_1');
+    expect(targetContents[1].conversationId).toBe('c_native_middle');
+    expect(targetContents[2].conversationId).toBe('c_existing_2');
+  });
+
+  it('successfully drops multiple native conversations (multi-select) into a folder conversation', () => {
+    const { typedManager, folderEl } = setupManagerWithFolder();
+
+    const convEls = folderEl.querySelectorAll('.gv-folder-conversation');
+    expect(convEls.length).toBe(2);
+
+    // Drop multiple conversations above c_existing_2
+    simulateDropOnConversation(
+      convEls[1] as HTMLElement,
+      {
+        type: 'conversation',
+        title: '2 conversations',
+        conversations: [
+          {
+            conversationId: 'c_multi_1',
+            title: 'Multi Conversation 1',
+            url: 'https://gemini.google.com/app/m1',
+            addedAt: Date.now(),
+          },
+          {
+            conversationId: 'c_multi_2',
+            title: 'Multi Conversation 2',
+            url: 'https://gemini.google.com/app/m2',
+            addedAt: Date.now(),
+          },
+        ],
+      },
+      true, // isAbove
+    );
+
+    const targetContents = typedManager.data.folderContents['folder-target'];
+    expect(targetContents.length).toBe(4);
+    expect(targetContents[0].conversationId).toBe('c_existing_1');
+    expect(targetContents[1].conversationId).toBe('c_multi_1');
+    expect(targetContents[2].conversationId).toBe('c_multi_2');
+    expect(targetContents[3].conversationId).toBe('c_existing_2');
+  });
+
+  it('moves a conversation from another folder when sourceFolderId is present', () => {
+    const { typedManager, folderEl } = setupManagerWithFolder();
+
+    // Set up source folder
+    typedManager.data.folderContents['folder-source'] = [
+      {
+        conversationId: 'c_from_source',
+        title: 'Source Conversation',
+        url: 'https://gemini.google.com/app/source',
+        addedAt: Date.now(),
+        sortIndex: 0,
+      },
+    ];
+
+    const convEls = folderEl.querySelectorAll('.gv-folder-conversation');
+
+    // Drop from folder-source above c_existing_1
+    simulateDropOnConversation(
+      convEls[0] as HTMLElement,
+      {
+        type: 'conversation',
+        conversationId: 'c_from_source',
+        title: 'Source Conversation',
+        url: 'https://gemini.google.com/app/source',
+        sourceFolderId: 'folder-source',
+      },
+      true,
+    );
+
+    expect(typedManager.data.folderContents['folder-source'].length).toBe(0);
+    expect(typedManager.data.folderContents['folder-target'].length).toBe(3);
+    expect(typedManager.data.folderContents['folder-target'][0].conversationId).toBe(
+      'c_from_source',
+    );
+  });
+
+  it('reorders conversations within the same folder without duplicates', () => {
+    const { typedManager, folderEl } = setupManagerWithFolder();
+
+    const convEls = folderEl.querySelectorAll('.gv-folder-conversation');
+
+    // Drag c_existing_2 and drop above c_existing_1
+    simulateDropOnConversation(
+      convEls[0] as HTMLElement,
+      {
+        type: 'conversation',
+        conversationId: 'c_existing_2',
+        title: 'Existing Conversation 2',
+        url: 'https://gemini.google.com/app/2',
+        sourceFolderId: 'folder-target',
+      },
+      true,
+    );
+
+    const targetContents = typedManager.data.folderContents['folder-target'];
+    expect(targetContents.length).toBe(2);
+    expect(targetContents[0].conversationId).toBe('c_existing_2');
+    expect(targetContents[1].conversationId).toBe('c_existing_1');
+  });
+});
