@@ -0,0 +1,262 @@
+package external
+
+import (
+	"bytes"
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+	"os"
+	"strconv"
+	"strings"
+
+	"github.com/entireio/cli/cmd/entire/cli/agent"
+)
+
+type hooksImpl struct{ ext *ExternalAgent }
+
+func (h hooksImpl) HookNames() []string {
+	return h.ext.info.HookNames
+}
+
+func (h hooksImpl) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
+	out, err := h.ext.exec(ctx, stdin, "parse-hook", "--hook", hookName)
+	if err != nil {
+		return nil, err
+	}
+	outStr := strings.TrimSpace(string(out))
+	if outStr == "" || outStr == "null" {
+		return nil, nil
+	}
+	var evt agent.Event
+	if err := json.Unmarshal(out, &evt); err != nil {
+		return nil, fmt.Errorf("failed to parse hook event: %w", err)
+	}
+	return &evt, nil
+}
+
+func (h hooksImpl) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
+	args := []string{}
+	if localDev {
+		args = append(args, "--local-dev")
+	}
+	if force {
+		args = append(args, "--force")
+	}
+	out, err := h.ext.exec(ctx, nil, "install-hooks", args...)
+	if err != nil {
+		return 0, err
+	}
+	var resp InstallHooksResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return 0, fmt.Errorf("failed to parse install-hooks response: %w", err)
+	}
+	return resp.HooksInstalled, nil
+}
+
+func (h hooksImpl) UninstallHooks(ctx context.Context) error {
+	_, err := h.ext.exec(ctx, nil, "uninstall-hooks")
+	return err
+}
+
+func (h hooksImpl) AreHooksInstalled(ctx context.Context) bool {
+	out, err := h.ext.exec(ctx, nil, "are-hooks-installed")
+	if err != nil {
+		return false
+	}
+	var resp InstalledResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return false
+	}
+	return resp.Installed
+}
+
+type analyzerImpl struct{ ext *ExternalAgent }
+
+func (a analyzerImpl) GetTranscriptPosition(path string) (int, error) {
+	out, err := a.ext.exec(context.Background(), nil, "get-transcript-position", "--path", path)
+	if err != nil {
+		return 0, err
+	}
+	var resp PositionResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return 0, fmt.Errorf("failed to parse transcript position: %w", err)
+	}
+	return resp.Position, nil
+}
+
+func (a analyzerImpl) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
+	out, err := a.ext.exec(context.Background(), nil, "extract-modified-files", "--path", path, "--offset", strconv.Itoa(startOffset))
+	if err != nil {
+		return nil, 0, err
+	}
+	var resp ExtractModifiedFilesResponse
+	if err := json.Unmarshal(out, &resp); err == nil && (len(resp.Files) > 0 || resp.CurrentPosition > 0) {
+		return resp.Files, resp.CurrentPosition, nil
+	}
+	var files []string
+	if err := json.Unmarshal(out, &files); err != nil {
+		return nil, 0, fmt.Errorf("failed to parse modified files: %w", err)
+	}
+	return files, startOffset, nil
+}
+
+type preparerImpl struct{ ext *ExternalAgent }
+
+func (p preparerImpl) PrepareTranscript(ctx context.Context, sessionRef string) error {
+	_, err := p.ext.exec(ctx, nil, "prepare-transcript", "--session-ref", sessionRef)
+	return err
+}
+
+type tokenCalcImpl struct{ ext *ExternalAgent }
+
+func (tc tokenCalcImpl) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
+	out, err := tc.ext.exec(context.Background(), bytes.NewReader(transcriptData), "calculate-tokens", "--offset", strconv.Itoa(fromOffset))
+	if err != nil {
+		return nil, err
+	}
+	var usage agent.TokenUsage
+	if err := json.Unmarshal(out, &usage); err != nil {
+		return nil, fmt.Errorf("failed to parse token usage: %w", err)
+	}
+	return &usage, nil
+}
+
+type textGenImpl struct{ ext *ExternalAgent }
+
+func (tg textGenImpl) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
+	out, err := tg.ext.exec(ctx, strings.NewReader(prompt), "generate-text", "--model", model)
+	if err != nil {
+		return "", err
+	}
+	var resp GenerateTextResponse
+	if err := json.Unmarshal(out, &resp); err == nil && resp.Text != "" {
+		return resp.Text, nil
+	}
+	return strings.TrimSpace(string(out)), nil
+}
+
+type hookRespWriterImpl struct{ ext *ExternalAgent }
+
+func (w hookRespWriterImpl) WriteHookResponse(message string) error {
+	out, err := w.ext.exec(context.Background(), nil, "write-hook-response", "--message", message)
+	if err != nil {
+		return err
+	}
+	if len(out) > 0 {
+		_, _ = os.Stdout.Write(out)
+	}
+	return nil
+}
+
+type subagentExtractorImpl struct{ ext *ExternalAgent }
+
+func (s subagentExtractorImpl) ExtractAllModifiedFiles(transcriptData []byte, fromOffset int, subagentsDir string) ([]string, error) {
+	out, err := s.ext.exec(context.Background(), bytes.NewReader(transcriptData), "extract-all-modified-files", "--offset", strconv.Itoa(fromOffset), "--subagents-dir", subagentsDir)
+	if err != nil {
+		return nil, err
+	}
+	var files []string
+	if err := json.Unmarshal(out, &files); err != nil {
+		return nil, fmt.Errorf("failed to parse extracted files: %w", err)
+	}
+	return files, nil
+}
+
+func (s subagentExtractorImpl) CalculateTotalTokenUsage(transcriptData []byte, fromOffset int, subagentsDir string) (*agent.TokenUsage, error) {
+	out, err := s.ext.exec(context.Background(), bytes.NewReader(transcriptData), "calculate-total-tokens", "--offset", strconv.Itoa(fromOffset), "--subagents-dir", subagentsDir)
+	if err != nil {
+		return nil, err
+	}
+	var usage agent.TokenUsage
+	if err := json.Unmarshal(out, &usage); err != nil {
+		return nil, fmt.Errorf("failed to parse total token usage: %w", err)
+	}
+	return &usage, nil
+}
+
+type agentH struct {
+	*ExternalAgent
+	hooksImpl
+}
+
+type agentA struct {
+	*ExternalAgent
+	analyzerImpl
+}
+
+type agentHA struct {
+	*ExternalAgent
+	hooksImpl
+	analyzerImpl
+}
+
+type agentHAP struct {
+	*ExternalAgent
+	hooksImpl
+	analyzerImpl
+	preparerImpl
+}
+
+type agentHAPS struct {
+	*ExternalAgent
+	hooksImpl
+	analyzerImpl
+	preparerImpl
+	subagentExtractorImpl
+}
+
+type agentHAPWS struct {
+	*ExternalAgent
+	hooksImpl
+	analyzerImpl
+	preparerImpl
+	hookRespWriterImpl
+	subagentExtractorImpl
+}
+
+type agentAll struct {
+	*ExternalAgent
+	hooksImpl
+	analyzerImpl
+	preparerImpl
+	tokenCalcImpl
+	textGenImpl
+	hookRespWriterImpl
+	subagentExtractorImpl
+}
+
+func wrapCapabilities(ext *ExternalAgent) agent.Agent {
+	c := ext.info.Capabilities
+	h := hooksImpl{ext: ext}
+	a := analyzerImpl{ext: ext}
+	p := preparerImpl{ext: ext}
+	tc := tokenCalcImpl{ext: ext}
+	tg := textGenImpl{ext: ext}
+	w := hookRespWriterImpl{ext: ext}
+	s := subagentExtractorImpl{ext: ext}
+
+	if c.Hooks && c.TranscriptAnalyzer && c.TranscriptPreparer && c.TokenCalculator && c.TextGenerator && c.HookResponseWriter && c.SubagentAwareExtractor {
+		return agentAll{ExternalAgent: ext, hooksImpl: h, analyzerImpl: a, preparerImpl: p, tokenCalcImpl: tc, textGenImpl: tg, hookRespWriterImpl: w, subagentExtractorImpl: s}
+	}
+	if c.Hooks && c.TranscriptAnalyzer && c.TranscriptPreparer && c.HookResponseWriter && c.SubagentAwareExtractor {
+		return agentHAPWS{ExternalAgent: ext, hooksImpl: h, analyzerImpl: a, preparerImpl: p, hookRespWriterImpl: w, subagentExtractorImpl: s}
+	}
+	if c.Hooks && c.TranscriptAnalyzer && c.TranscriptPreparer && c.SubagentAwareExtractor {
+		return agentHAPS{ExternalAgent: ext, hooksImpl: h, analyzerImpl: a, preparerImpl: p, subagentExtractorImpl: s}
+	}
+	if c.Hooks && c.TranscriptAnalyzer && c.TranscriptPreparer {
+		return agentHAP{ExternalAgent: ext, hooksImpl: h, analyzerImpl: a, preparerImpl: p}
+	}
+	if c.Hooks && c.TranscriptAnalyzer {
+		return agentHA{ExternalAgent: ext, hooksImpl: h, analyzerImpl: a}
+	}
+	if c.Hooks {
+		return agentH{ExternalAgent: ext, hooksImpl: h}
+	}
+	if c.TranscriptAnalyzer {
+		return agentA{ExternalAgent: ext, analyzerImpl: a}
+	}
+
+	return ext
+}
