new file mode 100644
index 0000000..3d1fe51
--- /dev/null
+++ b/cmd/entire/cli/agent/external/external.go
@@ -0,0 +1,223 @@
+package external
+
+import (
+	"bytes"
+	"context"
+	"encoding/base64"
+	"encoding/json"
+	"fmt"
+	"io"
+	"os"
+	"os/exec"
+	"strconv"
+	"strings"
+
+	"github.com/entireio/cli/cmd/entire/cli/agent"
+	"github.com/entireio/cli/cmd/entire/cli/agent/types"
+	"github.com/entireio/cli/cmd/entire/cli/paths"
+)
+
+func init() {
+	agent.ExternalAgentFactory = NewExternalAgent
+}
+
+// ExternalAgent implements agent.Agent by communicating with an external binary.
+type ExternalAgent struct {
+	binaryPath string
+	info       *InfoResponse
+}
+
+// NewExternalAgent instantiates an external agent by calling its `info` subcommand
+// and returning an agent wrapped with its declared capabilities.
+func NewExternalAgent(ctx context.Context, binaryPath string) (agent.Agent, error) {
+	ext := &ExternalAgent{binaryPath: binaryPath}
+	out, err := ext.exec(ctx, nil, "info")
+	if err != nil {
+		return nil, fmt.Errorf("failed to get info from external agent %s: %w", binaryPath, err)
+	}
+
+	var info InfoResponse
+	if err := json.Unmarshal(out, &info); err != nil {
+		return nil, fmt.Errorf("failed to parse info from external agent %s: %w", binaryPath, err)
+	}
+	ext.info = &info
+
+	return wrapCapabilities(ext), nil
+}
+
+func (e *ExternalAgent) exec(ctx context.Context, stdin io.Reader, subcommand string, args ...string) ([]byte, error) {
+	cmdArgs := append([]string{subcommand}, args...)
+	cmd := exec.CommandContext(ctx, e.binaryPath, cmdArgs...)
+	if stdin != nil {
+		cmd.Stdin = stdin
+	}
+
+	cmd.Env = append(os.Environ(), "ENTIRE_PROTOCOL_VERSION=1")
+	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil && repoRoot != "" {
+		cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
+		cmd.Dir = repoRoot
+	}
+
+	var stdout, stderr bytes.Buffer
+	cmd.Stdout = &stdout
+	cmd.Stderr = &stderr
+
+	if err := cmd.Run(); err != nil {
+		stderrStr := strings.TrimSpace(stderr.String())
+		if stderrStr != "" {
+			return nil, fmt.Errorf("external agent %s %s failed: %w: %s", e.binaryPath, subcommand, err, stderrStr)
+		}
+		return nil, fmt.Errorf("external agent %s %s failed: %w", e.binaryPath, subcommand, err)
+	}
+
+	return stdout.Bytes(), nil
+}
+
+func (e *ExternalAgent) Name() types.AgentName {
+	return e.info.Name
+}
+
+func (e *ExternalAgent) Type() types.AgentType {
+	return e.info.Type
+}
+
+func (e *ExternalAgent) Description() string {
+	return e.info.Description
+}
+
+func (e *ExternalAgent) IsPreview() bool {
+	return e.info.IsPreview
+}
+
+func (e *ExternalAgent) DetectPresence(ctx context.Context) (bool, error) {
+	out, err := e.exec(ctx, nil, "detect")
+	if err != nil {
+		return false, err
+	}
+	var resp PresentResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return false, fmt.Errorf("failed to parse detect response: %w", err)
+	}
+	return resp.Present, nil
+}
+
+func (e *ExternalAgent) ProtectedDirs() []string {
+	return e.info.ProtectedDirs
+}
+
+func (e *ExternalAgent) ReadTranscript(sessionRef string) ([]byte, error) {
+	return e.exec(context.Background(), nil, "read-transcript", "--session-ref", sessionRef)
+}
+
+func (e *ExternalAgent) ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error) {
+	out, err := e.exec(ctx, bytes.NewReader(content), "chunk-transcript", "--max-size", strconv.Itoa(maxSize))
+	if err != nil {
+		return nil, err
+	}
+	var resp ChunksResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return nil, fmt.Errorf("failed to parse chunk-transcript response: %w", err)
+	}
+
+	chunks := make([][]byte, len(resp.Chunks))
+	for i, chunkStr := range resp.Chunks {
+		decoded, err := base64.StdEncoding.DecodeString(chunkStr)
+		if err != nil {
+			// Fall back to raw bytes if not base64
+			chunks[i] = []byte(chunkStr)
+		} else {
+			chunks[i] = decoded
+		}
+	}
+	return chunks, nil
+}
+
+func (e *ExternalAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
+	encoded := make([]string, len(chunks))
+	for i, chunk := range chunks {
+		encoded[i] = base64.StdEncoding.EncodeToString(chunk)
+	}
+	reqData, err := json.Marshal(ChunksRequest{Chunks: encoded})
+	if err != nil {
+		return nil, fmt.Errorf("failed to marshal reassemble-transcript request: %w", err)
+	}
+
+	return e.exec(context.Background(), bytes.NewReader(reqData), "reassemble-transcript")
+}
+
+func (e *ExternalAgent) GetSessionID(input *agent.HookInput) string {
+	data, err := json.Marshal(input)
+	if err != nil {
+		return ""
+	}
+	out, err := e.exec(context.Background(), bytes.NewReader(data), "get-session-id")
+	if err != nil {
+		return ""
+	}
+	var resp SessionIDResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return ""
+	}
+	return resp.SessionID
+}
+
+func (e *ExternalAgent) GetSessionDir(repoPath string) (string, error) {
+	out, err := e.exec(context.Background(), nil, "get-session-dir", "--repo-path", repoPath)
+	if err != nil {
+		return "", err
+	}
+	var resp SessionDirResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return "", fmt.Errorf("failed to parse get-session-dir response: %w", err)
+	}
+	return resp.SessionDir, nil
+}
+
+func (e *ExternalAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
+	out, err := e.exec(context.Background(), nil, "resolve-session-file", "--session-dir", sessionDir, "--session-id", agentSessionID)
+	if err != nil {
+		return ""
+	}
+	var resp SessionFileResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return ""
+	}
+	return resp.SessionFile
+}
+
+func (e *ExternalAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
+	data, err := json.Marshal(input)
+	if err != nil {
+		return nil, fmt.Errorf("failed to marshal hook input: %w", err)
+	}
+	out, err := e.exec(context.Background(), bytes.NewReader(data), "read-session")
+	if err != nil {
+		return nil, err
+	}
+	var sess agent.AgentSession
+	if err := json.Unmarshal(out, &sess); err != nil {
+		return nil, fmt.Errorf("failed to parse read-session response: %w", err)
+	}
+	return &sess, nil
+}
+
+func (e *ExternalAgent) WriteSession(ctx context.Context, session *agent.AgentSession) error {
+	data, err := json.Marshal(session)
+	if err != nil {
+		return fmt.Errorf("failed to marshal session: %w", err)
+	}
+	_, err = e.exec(ctx, bytes.NewReader(data), "write-session")
+	return err
+}
+
+func (e *ExternalAgent) FormatResumeCommand(sessionID string) string {
+	out, err := e.exec(context.Background(), nil, "format-resume-command", "--session-id", sessionID)
+	if err != nil {
+		return ""
+	}
+	var resp ResumeCommandResponse
+	if err := json.Unmarshal(out, &resp); err != nil {
+		return ""
+	}
+	return resp.Command
+}
