+)
+
+func createMockAgentBinary(t *testing.T, scriptContent string) string {
+	t.Helper()
+	dir := t.TempDir()
+	binPath := filepath.Join(dir, "entire-agent-test")
+	err := os.WriteFile(binPath, []byte("#!/bin/sh\n"+scriptContent), 0755)
+	if err != nil {
+		t.Fatalf("failed to write mock agent script: %v", err)
+	}
+	return binPath
+}
+
+func TestExternalAgent_BasicAndCapabilities(t *testing.T) {
+	t.Parallel()
+
+	script := `
+case "$1" in
+  info)
+    echo '{"protocol_version":1,"name":"test-agent","type":"TestAgent","description":"Test Agent","is_preview":true,"protected_dirs":[".test"],"hook_names":["stop"],"capabilities":{"hooks":true,"transcript_analyzer":true,"transcript_preparer":false}}'
+    ;;
+  detect)
+    echo '{"present":true}'
+    ;;
+  read-transcript)
+    echo "transcript content"
+    ;;
+  chunk-transcript)
+    echo '{"chunks":["Y2h1bmsx","Y2h1bmsy"]}' # base64 "chunk1", "chunk2"
+    ;;
+  reassemble-transcript)
+    echo "reassembled"
+    ;;
+  get-session-id)
+    echo '{"session_id":"sess-123"}'
+    ;;
+  get-session-dir)
+    echo '{"session_dir":"/path/to/session"}'
+    ;;
+  resolve-session-file)
+    echo '{"session_file":"/path/to/session/file.json"}'
+    ;;
+  format-resume-command)
+    echo '{"command":"test resume"}'
+    ;;
+  parse-hook)
+    echo '{"Type":1,"SessionID":"sess-123"}'
+    ;;
+  install-hooks)
+    echo '{"hooks_installed":2}'
+    ;;
+  uninstall-hooks)
+    exit 0
+    ;;
+  are-hooks-installed)
+    echo '{"installed":true}'
+    ;;
+  get-transcript-position)
+    echo '{"position":42}'
+    ;;
+  extract-modified-files)
+    echo '{"files":["foo.go","bar.go"],"current_position":42}'
+    ;;
+  *)
+    echo "Unknown subcommand: $1" >&2
+    exit 1
+    ;;
+esac
+`
+
+	binPath := createMockAgentBinary(t, script)
+	ctx := context.Background()
+
+	ag, err := external.NewExternalAgent(ctx, binPath)
+	if err != nil {
+		t.Fatalf("failed to create ExternalAgent: %v", err)
+	}
+
+	if ag.Name() != types.AgentName("test-agent") {
+		t.Errorf("expected name 'test-agent', got '%s'", ag.Name())
+	}
+	if ag.Type() != types.AgentType("TestAgent") {
+		t.Errorf("expected type 'TestAgent', got '%s'", ag.Type())
+	}
+	if ag.Description() != "Test Agent" {
+		t.Errorf("expected description 'Test Agent', got '%s'", ag.Description())
+	}
+	if !ag.IsPreview() {
+		t.Errorf("expected IsPreview true")
+	}
+	if dirs := ag.ProtectedDirs(); len(dirs) != 1 || dirs[0] != ".test" {
+		t.Errorf("unexpected protected dirs: %v", dirs)
+	}
+
+	present, err := ag.DetectPresence(ctx)
+	if err != nil || !present {
+		t.Errorf("expected presence true, got %v, err=%v", present, err)
+	}
+
+	transcript, err := ag.ReadTranscript("ref")
+	if err != nil || string(transcript) != "transcript content\n" {
+		t.Errorf("unexpected transcript: %s, err=%v", string(transcript), err)
+	}
+
+	chunks, err := ag.ChunkTranscript(ctx, []byte("content"), 100)
+	if err != nil || len(chunks) != 2 || string(chunks[0]) != "chunk1" || string(chunks[1]) != "chunk2" {
+		t.Errorf("unexpected chunks: %v, err=%v", chunks, err)
+	}
+
+	reassembled, err := ag.ReassembleTranscript(chunks)
+	if err != nil || string(reassembled) != "reassembled\n" {
+		t.Errorf("unexpected reassembled: %s, err=%v", string(reassembled), err)
+	}
+
+	if sessID := ag.GetSessionID(&agent.HookInput{}); sessID != "sess-123" {
+		t.Errorf("expected sess-123, got %s", sessID)
+	}
+
+	if sessDir, err := ag.GetSessionDir("/repo"); err != nil || sessDir != "/path/to/session" {
+		t.Errorf("unexpected session dir: %s, err=%v", sessDir, err)
+	}
+
+	if sessFile := ag.ResolveSessionFile("/dir", "id"); sessFile != "/path/to/session/file.json" {
+		t.Errorf("unexpected session file: %s", sessFile)
+	}
+
+	if cmd := ag.FormatResumeCommand("id"); cmd != "test resume" {
+		t.Errorf("unexpected resume command: %s", cmd)
+	}
+
+	// Test capability assertions
+	hookAgent, ok := ag.(agent.HookSupport)
+	if !ok {
+		t.Fatalf("expected agent to implement HookSupport")
+	}
+	if names := hookAgent.HookNames(); len(names) != 1 || names[0] != "stop" {
+		t.Errorf("unexpected hook names: %v", names)
+	}
+
+	installed, err := hookAgent.InstallHooks(ctx, false, false)
+	if err != nil || installed != 2 {
+		t.Errorf("unexpected install hooks result: %d, err=%v", installed, err)
+	}
+
+	if !hookAgent.AreHooksInstalled(ctx) {
+		t.Errorf("expected hooks installed true")
+	}
+
+	if err := hookAgent.UninstallHooks(ctx); err != nil {
+		t.Errorf("uninstall hooks failed: %v", err)
+	}
+
+	analyzerAgent, ok := ag.(agent.TranscriptAnalyzer)
+	if !ok {
+		t.Fatalf("expected agent to implement TranscriptAnalyzer")
+	}
+
+	pos, err := analyzerAgent.GetTranscriptPosition("path")
+	if err != nil || pos != 42 {
+		t.Errorf("unexpected position: %d, err=%v", pos, err)
+	}
+
+	files, currentPos, err := analyzerAgent.ExtractModifiedFilesFromOffset("path", 0)
+	if err != nil || len(files) != 2 || currentPos != 42 {
+		t.Errorf("unexpected modified files: %v, pos=%d, err=%v", files, currentPos, err)
+	}
+
+	// Test disabled capability (TranscriptPreparer)
+	_, ok = ag.(agent.TranscriptPreparer)
+	if ok {
+		t.Errorf("expected agent NOT to implement TranscriptPreparer")
+	}
+}
+
+func TestExternalAgent_Errors(t *testing.T) {
+	t.Parallel()
+
+	ctx := context.Background()
+
+	// Non-existent binary
+	_, err := external.NewExternalAgent(ctx, "/path/does/not/exist/entire-agent-foo")
+	if err == nil {
+		t.Errorf("expected error for non-existent binary")
+	}
+
+	// Binary exits with error
+	script := `
+echo "something went wrong" >&2
+exit 1
+`
+	binPath := createMockAgentBinary(t, script)
+	_, err = external.NewExternalAgent(ctx, binPath)
+	if err == nil {
+		t.Errorf("expected error for failing binary")
+	}
+}
