+package external
+
+import (
+	"github.com/entireio/cli/cmd/entire/cli/agent/types"
+)
+
+// Capabilities declares which optional agent interfaces are supported by an external agent binary.
+type Capabilities struct {
+	Hooks                  bool `json:"hooks"`
+	TranscriptAnalyzer     bool `json:"transcript_analyzer"`
+	TranscriptPreparer     bool `json:"transcript_preparer"`
+	TokenCalculator        bool `json:"token_calculator"`
+	TextGenerator          bool `json:"text_generator"`
+	HookResponseWriter     bool `json:"hook_response_writer"`
+	SubagentAwareExtractor bool `json:"subagent_aware_extractor"`
+}
+
+// InfoResponse is returned by the `info` subcommand.
+type InfoResponse struct {
+	ProtocolVersion int             `json:"protocol_version"`
+	Name            types.AgentName `json:"name"`
+	Type            types.AgentType `json:"type"`
+	Description     string          `json:"description"`
+	IsPreview       bool            `json:"is_preview"`
+	ProtectedDirs   []string        `json:"protected_dirs"`
+	HookNames       []string        `json:"hook_names"`
+	Capabilities    Capabilities    `json:"capabilities"`
+}
+
+// PresentResponse is returned by the `detect` subcommand.
+type PresentResponse struct {
+	Present bool `json:"present"`
+}
+
+// ChunksResponse is returned by `chunk-transcript`.
+type ChunksResponse struct {
+	Chunks []string `json:"chunks"`
+}
+
+// ChunksRequest is passed to `reassemble-transcript`.
+type ChunksRequest struct {
+	Chunks []string `json:"chunks"`
+}
+
+// SessionIDResponse is returned by `get-session-id`.
+type SessionIDResponse struct {
+	SessionID string `json:"session_id"`
+}
+
+// SessionDirResponse is returned by `get-session-dir`.
+type SessionDirResponse struct {
+	SessionDir string `json:"session_dir"`
+}
+
+// SessionFileResponse is returned by `resolve-session-file`.
+type SessionFileResponse struct {
+	SessionFile string `json:"session_file"`
+}
+
+// ResumeCommandResponse is returned by `format-resume-command`.
+type ResumeCommandResponse struct {
+	Command string `json:"command"`
+}
+
+// InstallHooksResponse is returned by `install-hooks`.
+type InstallHooksResponse struct {
+	HooksInstalled int `json:"hooks_installed"`
+}
+
+// InstalledResponse is returned by `are-hooks-installed`.
+type InstalledResponse struct {
+	Installed bool `json:"installed"`
+}
+
+// PositionResponse is returned by `get-transcript-position`.
+type PositionResponse struct {
+	Position int `json:"position"`
+}
+
+// ExtractModifiedFilesResponse is returned by `extract-modified-files`.
+type ExtractModifiedFilesResponse struct {
+	Files           []string `json:"files"`
+	CurrentPosition int      `json:"current_position"`
+}
+
+// SummaryResponse is returned by `extract-summary`.
+type SummaryResponse struct {
+	Summary string `json:"summary"`
+}
+
+// GenerateTextResponse is returned by `generate-text`.
+type GenerateTextResponse struct {
+	Text string `json:"text"`
+}
