+func DiscoverExternal() {
+	if ExternalAgentFactory == nil {
+		return
+	}
+
+	pathEnv := os.Getenv("PATH")
+	if pathEnv == "" {
+		return
+	}
+
+	dirs := filepath.SplitList(pathEnv)
+	seenBinaries := make(map[string]bool)
+
+	for _, dir := range dirs {
+		if dir == "" {
+			continue
+		}
+		entries, err := os.ReadDir(dir)
+		if err != nil {
+			continue
+		}
+
+		for _, entry := range entries {
+			if entry.IsDir() {
+				continue
+			}
+
+			name := entry.Name()
+			if !strings.HasPrefix(name, "entire-agent-") {
+				continue
+			}
+
+			agentNameStr := strings.TrimPrefix(name, "entire-agent-")
+			if agentNameStr == "" {
+				continue
+			}
+
+			// Strip .exe on Windows if present
+			if strings.HasSuffix(agentNameStr, ".exe") {
+				agentNameStr = strings.TrimSuffix(agentNameStr, ".exe")
+			}

+			agentName := types.AgentName(agentNameStr)
+
+			registryMu.RLock()
+			_, exists := registry[agentName]
+			registryMu.RUnlock()
+
+			if exists {
+				continue
+			}
+
+			binaryPath := filepath.Join(dir, name)
+			if seenBinaries[binaryPath] {
+				continue
+			}
+			seenBinaries[binaryPath] = true
+
+			// Verify binary is executable
+			info, err := entry.Info()
+			if err != nil {
+				continue
+			}
+			if runtime.GOOS != "windows" && (info.Mode()&0111) == 0 {
+				continue
+			}
+
+			ctx := context.Background()
+			if _, err := ExternalAgentFactory(ctx, binaryPath); err != nil {
+				continue
+			}
+
+			capturedPath := binaryPath
+			Register(agentName, func() Agent {
+				ag, err := ExternalAgentFactory(context.Background(), capturedPath)
+				if err != nil {
+					return nil
+				}
+				return ag
+			})
+		}
+	}
+}
