diff --git a/cmd/entire/cli/telemetry/detached_unix_test.go b/cmd/entire/cli/telemetry/detached_unix_test.go
new file mode 100644
index 0000000..7dbbf28
--- /dev/null
+++ b/cmd/entire/cli/telemetry/detached_unix_test.go
@@ -0,0 +1,44 @@
+//go:build unix
+
+package telemetry
+
+import (
+	"os"
+	"testing"
+)
+
+func TestNewDetachedAnalyticsCmd(t *testing.T) {
+	devNull, err := os.OpenFile(os.DevNull, os.O_WRONLY, 0)
+	if err != nil {
+		t.Fatalf("Failed to open %s: %v", os.DevNull, err)
+	}
+	defer func() {
+		_ = devNull.Close()
+	}()
+
+	executable := "/usr/bin/entire"
+	payload := `{"event":"test"}`
+	cmd := newDetachedAnalyticsCmd(executable, payload, devNull)
+
+	if cmd.Stdout == nil {
+		t.Fatal("expected cmd.Stdout not to be nil")
+	}
+	if cmd.Stdout != devNull {
+		t.Errorf("cmd.Stdout = %v, want %v", cmd.Stdout, devNull)
+	}
+	if cmd.Stderr == nil {
+		t.Fatal("expected cmd.Stderr not to be nil")
+	}
+	if cmd.Stderr != devNull {
+		t.Errorf("cmd.Stderr = %v, want %v", cmd.Stderr, devNull)
+	}
+	if cmd.Dir != "/" {
+		t.Errorf("cmd.Dir = %q, want \"/\"", cmd.Dir)
+	}
+	if cmd.SysProcAttr == nil || !cmd.SysProcAttr.Setpgid {
+		t.Error("cmd.SysProcAttr.Setpgid should be true")
+	}
+	if len(cmd.Args) != 3 || cmd.Args[0] != executable || cmd.Args[1] != "__send_analytics" || cmd.Args[2] != payload {
+		t.Errorf("unexpected cmd.Args: %v", cmd.Args)
+	}
+}

