+// DuplicateCommitted copies an existing committed checkpoint to a new checkpoint ID.
+// This is used when consecutive commits reference the same session work, ensuring
+// each commit receives a unique checkpoint ID on entire/checkpoints/v1.
+func (s *GitStore) DuplicateCommitted(ctx context.Context, srcID, dstID id.CheckpointID) error {
+	_ = ctx
+	if srcID.IsEmpty() || dstID.IsEmpty() {
+		return errors.New("source and destination checkpoint IDs are required")
+	}
+
+	if err := s.ensureSessionsBranch(); err != nil {
+		return fmt.Errorf("failed to ensure sessions branch: %w", err)
+	}
+
+	ref, entries, err := s.getSessionsBranchEntries()
+	if err != nil {
+		return err
+	}
+
+	srcPrefix := srcID.Path() + "/"
+	dstPrefix := dstID.Path() + "/"
+
+	found := false
+	var sessionID string
+	var strategyName string
+
+	for path, entry := range entries {
+		if strings.HasPrefix(path, srcPrefix) {
+			found = true
+			relPath := strings.TrimPrefix(path, srcPrefix)
+			newPath := dstPrefix + relPath
+
+			if relPath == paths.MetadataFileName || strings.HasSuffix(relPath, "/"+paths.MetadataFileName) {
+				blob, err := s.repo.BlobObject(entry.Hash)
+				if err != nil {
+					return fmt.Errorf("failed to read blob %s: %w", path, err)
+				}
+				reader, err := blob.Reader()
+				if err != nil {
+					return fmt.Errorf("failed to open blob reader %s: %w", path, err)
+				}
+				content, err := io.ReadAll(reader)
+				_ = reader.Close()
+				if err != nil {
+					return fmt.Errorf("failed to read blob content %s: %w", path, err)
+				}
+
+				if relPath == paths.MetadataFileName {
+					var summary CheckpointSummary
+					if jsonErr := json.Unmarshal(content, &summary); jsonErr == nil {
+						strategyName = summary.Strategy
+					}
+				}
+				if strings.HasSuffix(relPath, "/"+paths.MetadataFileName) {
+					var meta CommittedMetadata
+					if jsonErr := json.Unmarshal(content, &meta); jsonErr == nil {
+						sessionID = meta.SessionID
+						if strategyName == "" {
+							strategyName = meta.Strategy
+						}
+					}
+				}
+
+				updatedContent := bytes.ReplaceAll(content, []byte(srcID.String()), []byte(dstID.String()))
+				newBlobHash, err := CreateBlobFromContent(s.repo, updatedContent)
+				if err != nil {
+					return fmt.Errorf("failed to create blob %s: %w", newPath, err)
+				}
+				entries[newPath] = object.TreeEntry{
+					Name: newPath,
+					Mode: entry.Mode,
+					Hash: newBlobHash,
+				}
+			} else {
