+// duplicateCheckpointAndUpdateState duplicates checkpoint metadata from srcID to dstID
+// on entire/checkpoints/v1 and updates the session state for the new commit.
+func (s *ManualCommitStrategy) duplicateCheckpointAndUpdateState(
+	logCtx context.Context,
+	repo *git.Repository,
+	srcID, dstID id.CheckpointID,
+	state *SessionState,
+	head *plumbing.Reference,
+) {
+	store := checkpoint.NewGitStore(repo)
+	if err := store.DuplicateCommitted(context.Background(), srcID, dstID); err != nil {
+		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to duplicate checkpoint metadata from %s to %s: %v\n",
+			srcID, dstID, err)
+		logging.Warn(logCtx, "post-commit: failed to duplicate checkpoint metadata",
+			slog.String("src_checkpoint_id", srcID.String()),
+			slog.String("dst_checkpoint_id", dstID.String()),
+			slog.String("error", err.Error()),
+		)
+		return
+	}
+
+	newHead := head.Hash().String()
+	state.BaseCommit = newHead
+	state.AttributionBaseCommit = newHead
+	state.StepCount = 0
+	state.FilesTouched = nil
+	state.LastCheckpointID = dstID
+	state.PendingCheckpointID = ""
+
+	shortID := state.SessionID
+	if len(shortID) > 8 {
+		shortID = shortID[:8]
+	}
+	fmt.Fprintf(os.Stderr, "[entire] Linked checkpoint %s for session %s\n",
+		dstID, shortID)
+
+	logging.Info(logCtx, "checkpoint duplicated for consecutive commit",
+		slog.String("strategy", "manual-commit"),
+		slog.String("checkpoint_id", dstID.String()),
+		slog.String("parent_checkpoint_id", srcID.String()),
+	)
+}
