+import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
+
+import { FolderManager } from '../manager';
+import type { Folder, FolderData } from '../types';
+
+vi.mock('@/utils/i18n', () => ({
+  getTranslationSync: (key: string) => key,
+  getTranslationSyncUnsafe: (key: string) => key,
+  initI18n: () => Promise.resolve(),
+}));
+
+type TestableManager = {
+  data: FolderData;
+  createFolderElement: (folder: Folder, level?: number) => HTMLElement;
+  clearAllDragOverStyles: () => void;
+  reorderOrMoveConversations: (
+    conversationIds: string[],
+    sourceParentId: string | undefined,
+    targetParentId: string,
+    insertIndex: number,
+    dragData?: unknown,
+  ) => void;
+  saveData: () => void;
+  refresh: () => void;
+};
+
+function createFolder(): Folder {
+  const now = Date.now();
+  return {
+    id: 'folder-1',
+    name: 'Folder 1',
+    parentId: null,
+    isExpanded: true,
+    createdAt: now,
+    updatedAt: now,
+  };
+}
+
+describe('folder drag and drop behavior', () => {
+  let manager: FolderManager | null = null;
+
+  beforeEach(() => {
+    vi.useFakeTimers();
+  });
+
+  afterEach(() => {
+    manager?.destroy();
+    manager = null;
+    document.body.innerHTML = '';
+    vi.runOnlyPendingTimers();
+    vi.useRealTimers();
+  });
+
+  it('adds native conversation into folder when dropped onto a conversation inside the folder', () => {
+    manager = new FolderManager();
+    const typedManager = manager as unknown as TestableManager;
+
+    const folder = createFolder();
+    typedManager.data = {
+      folders: [folder],
+      folderContents: {
+        'folder-1': [
+          {
+            conversationId: 'existing-conv-1',
+            title: 'Existing Chat',
+            url: 'https://gemini.google.com/app/1',
+            addedAt: Date.now(),
+            sortIndex: 0,
+          },
+        ],
+      },
+    };
+
+    const nativeDragData = {
+      type: 'conversation',
+      conversationId: 'native-conv-1',
+      title: 'Native Chat 1',
+      url: 'https://gemini.google.com/app/native-1',
+    };
+
+    typedManager.reorderOrMoveConversations(
+      ['native-conv-1'],
+      undefined,
+      'folder-1',
+      0,
+      nativeDragData,
+    );
+
+    const folderConvs = typedManager.data.folderContents['folder-1'];
+    expect(folderConvs.length).toBe(2);
+    expect(folderConvs[0].conversationId).toBe('native-conv-1');
+    expect(folderConvs[1].conversationId).toBe('existing-conv-1');
+  });
+
+  it('inserts conversation precisely at target position when folder contains multiple conversations', () => {
+    manager = new FolderManager();
+    const typedManager = manager as unknown as TestableManager;
+
+    const folder = createFolder();
+    typedManager.data = {
+      folders: [folder],
+      folderContents: {
+        'folder-1': [
+          {
+            conversationId: 'conv-0',
+            title: 'Chat 0',
+            url: 'https://gemini.google.com/app/0',
+            addedAt: Date.now(),
+            sortIndex: 0,
+          },
+          {
+            conversationId: 'conv-1',
+            title: 'Chat 1',
+            url: 'https://gemini.google.com/app/1',
+            addedAt: Date.now(),
+            sortIndex: 1,
+          },
+          {
+            conversationId: 'conv-2',
+            title: 'Chat 2',
+            url: 'https://gemini.google.com/app/2',
+            addedAt: Date.now(),
+            sortIndex: 2,
+          },
+        ],
+      },
+    };
+
+    const nativeDragData = {
+      type: 'conversation',
+      conversationId: 'native-new',
+      title: 'New Chat',
+      url: 'https://gemini.google.com/app/new',
+    };
+
+    // Insert at index 1 (between conv-0 and conv-1)
+    typedManager.reorderOrMoveConversations(
+      ['native-new'],
+      undefined,
+      'folder-1',
+      1,
+      nativeDragData,
+    );
+
+    const folderConvs = typedManager.data.folderContents['folder-1'];
+    expect(folderConvs.length).toBe(4);
+    expect(folderConvs[0].conversationId).toBe('conv-0');
+    expect(folderConvs[1].conversationId).toBe('native-new');
+    expect(folderConvs[2].conversationId).toBe('conv-1');
+    expect(folderConvs[3].conversationId).toBe('conv-2');
+  });
+
+  it('clears all dragover highlight classes on clearAllDragOverStyles', () => {
+    manager = new FolderManager();
