+
+    const container = document.createElement('div');
+    container.className = 'gv-folder-container';
+
+    const header = document.createElement('div');
+    header.className = 'gv-folder-item-header gv-folder-dragover';
+
+    const gap = document.createElement('div');
+    gap.className = 'gv-reorder-gap gv-reorder-gap-active';
+
+    const conv = document.createElement('div');
+    conv.className = 'gv-folder-conversation gv-reorder-above';
+
+    container.appendChild(header);
+    container.appendChild(gap);
+    container.appendChild(conv);
+    document.body.appendChild(container);
+
+    typedManager.clearAllDragOverStyles();
+
+    expect(header.classList.contains('gv-folder-dragover')).toBe(false);
+    expect(gap.classList.contains('gv-reorder-gap-active')).toBe(false);
+    expect(conv.classList.contains('gv-reorder-above')).toBe(false);
+  });
+});
